+}
+
+function quoteValue(value: string): string {
+  if (PLAIN_VALUE_PATTERN.test(value)) return value;
+  return `"${value.replace(/[\\"$\n\r]/g, (char) => ESCAPES[char])}"`;
 }

 /** Render variables as the lines of a dotenv file. */
 export function renderEnvFile(vars: Record<string, string>): string {
-  throw new Error("not implemented");
+  return Object.keys(vars)
+    .sort()
+    .map((name) => {
+      if (!NAME_PATTERN.test(name)) throw new RangeError(`invalid variable name: ${name}`);
+      return `${name}=${quoteValue(vars[name])}\n`;
+    })
+    .join("");
 }

